function abgCase(){ const sc = pick(ABGSC), g = abgMake(sc.type, sc.c, sc.ag || 'n'), parts = [];
  const st = abgStatus(g);
  parts.push({q:"Step 1 – what is the pH status?|Étape 1 – quel est l'état du pH ?|Schritt 1 – wie ist der pH-Status?", o:[st].concat([ABG.phA, ABG.phK, ABG.phN].filter(x => x !== st)),
    x:q3x("pH {ph}: normal range 7.35–7.45.|pH {ph} : normes 7,35–7,45.|pH {ph}: Normbereich 7,35–7,45.", {ph:n3(g.ph.toFixed(2))})});
  parts.push({q:"Step 2 – what is the primary disorder?|Étape 2 – quel est le trouble primaire ?|Schritt 2 – was ist die primäre Störung?", o:[ABG[g.type]].concat(['macid', 'malk', 'racid', 'ralk'].filter(x => x !== g.type).map(x => ABG[x])), x:abgPrimaryX(g)});
  const cq = abgCompQ(g); parts.push({q:abgStep3(cq.q), o:cq.o, x:cq.x});
  if (g.type === 'macid') parts.push({q:"Step 4 – what is the anion gap?|Étape 4 – quel est le trou anionique ?|Schritt 4 – wie ist die Anionenlücke?", o:sc.ag === 'h' ? [ABG.agH, ABG.agN] : [ABG.agN, ABG.agH],
    x:q3x("AG = Na⁺ − (Cl⁻ + HCO₃⁻) = {na} − ({cl} + {h}) = {ag} mmol/L (normal ≈ 8–12).|TA = Na⁺ − (Cl⁻ + HCO₃⁻) = {na} − ({cl} + {h}) = {ag} mmol/L (normale ≈ 8–12).|AL = Na⁺ − (Cl⁻ + HCO₃⁻) = {na} − ({cl} + {h}) = {ag} mmol/l (normal ≈ 8–12).", {na:n3(g.na), cl:n3(g.cl), h:n3(g.h), ag:n3(g.ag)})});
  const others = shuffle(ABGSC.filter(z => z !== sc && z.type === sc.type).concat(shuffle(ABGSC.filter(z => z.type !== sc.type)))).filter((z, i, a) => a.findIndex(y => y.a === z.a) === i).slice(0, 3);
  parts.push({q:"Final step – the most likely cause?|Dernière étape – la cause la plus probable ?|Letzter Schritt – die wahrscheinlichste Ursache?", o:[sc.a].concat(others.map(z => z.a)), x:sc.x});
  return {k:'case', t:'chain', stem:sc.s, stemh:abgFig(g, g.type === 'macid'), parts}; }
/* fix the step-3 label in all three languages */
function abgStep3(q){ const p = q.split('|'); return ["Step 3 – " + p[0], "Étape 3 – " + (p[1] || p[0]), "Schritt 3 – " + (p[2] || p[0])].join('|'); }
